const fs=require('fs'),path=require('path'),p=n=>path.join(__dirname,n);
for(const admin of[false,true]){let html=fs.readFileSync(p('shell.html'),'utf8');const modules=[['STYLES','styles.css'],['PEER','peerjs.min.js'],['ENGINE','engine.js'],['CONTROLS','controls.js'],['SCENERY','scenery.js'],['SCENERY_EXTRA','scenery-extra.js'],['SKINS','skins.js'],['EDITOR','editor.js'],['WEAPONS','weapons.js'],['ACTORS','actors.js'],['LIGHTING','lighting.js'],['AUDIO','audio.js'],['SESSION','session.js'],['RENDERER','renderer.js'],['NETWORK','network.js'],['LAB','lab.js'],['SPECIAL_UI','special-ui.js'],['APP','app.js']];
 for(const[marker,file]of modules)html=html.replace('/* '+marker+' */',()=>{let text=fs.readFileSync(p(file),'utf8');if(file==='styles.css')text+='\n'+['v3.css','arenas.css','v33.css','v4.css','v42.css','v43.css','v5.css'].map(f=>fs.readFileSync(p(f),'utf8')).join('\n');return text.replace(/<\/script/gi,'<\\/script').replace(/\/\/# sourceMappingURL=.*$/gm,'');});
 html=html.replace('<!-- ADMIN_HTML -->',()=>admin?fs.readFileSync(p('admin.html'),'utf8'):'').replace('/* ADMIN */',()=>admin?fs.readFileSync(p('admin.js'),'utf8'):'').replace('/* LICENSE */',()=>'/*\n'+fs.readFileSync(p('PEERJS-LICENSE.txt'),'utf8')+'\n*/');if(admin)html=html.replace('download="UM-CORTE-V5.html"','download="UM-CORTE-V5-ADMIN.html"').replace('<title>','<title>ADMIN · ');const out=p('../../outputs/um-corte-v5'+(admin?'-admin':'')+'.html');fs.writeFileSync(out,html);console.log(out);}
